class Point3D extends Point {
    final int z;

    @Override
    public boolean equals(Object o) {
        if (o instanceof Point3D other) {
            return x == other.x && y == other.y && z == other.z;
        }
        if (o instanceof Point p) {          // accept a plain Point too
            return x == p.x && y == p.y;     // ...by ignoring z
        }
        return false;
    }
}

// Both classes start equals() with:
//   if (o == null || getClass() != o.getClass()) return false;

Point   p = new Point(1, 2);
Point3D a = new Point3D(1, 2, 10);
Point3D b = new Point3D(1, 2, 10);

System.out.println(p.equals(a) + " " + a.equals(p) + " " + a.equals(b));
